function rd(mode){return g.CpcM20NativeReader?.stats?g.CpcM20NativeReader.stats(mode):{done:0,total:mode==='summary'?5:60}}
function P(){const m=M(),a=rd('summary'),b=rd('complete');return Math.round(((m.map?1:0)+a.done+(qDone('summary')?5:0)+b.done+(qDone('complete')?10:0)+(m.decorando?1:0))/(1+a.total+5+b.total+10+1)*100)}
function E(s){return String(s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function map(){if(document.getElementById('m20map'))return;const o=document.createElement('div');o.id='m20map';o.className='bc-cpc-map-overlay';o.innerHTML='<div class="bc-cpc-map-overlay-head"><div><b>CPC M20 — Mapa Mental</b><span>Fechamento de Processo Civil</span></div><button class="bc-cpc-map-close" onclick="cpcM20CloseMap()">← Voltar ao M20</button></div><iframe class="bc-cpc-map-frame" src="tools/cpc-m20-mapa.html"></iframe>';document.body.appendChild(o);document.documentElement.style.overflow='hidden';document.body.style.overflow='hidden'}
