function renderQuiz(){if(!quiz)return;const q=quiz.list[quiz.i],n=quiz.i+1,total=quiz.list.length;quiz.answered=false;quiz.host.innerHTML='<div class="bc-native-kicker">QUESTÃO '+n+' DE '+total+' • '+E(q.d)+'</div><h1 style="font-size:1.55em">'+E(q.q)+'</h1><div>'+q.o.map((x,i)=>'<button class="cf-btn" data-opt="'+i+'" style="display:block;width:100%;text-align:left;margin:8px 0;padding:13px">'+String.fromCharCode(65+i)+') '+E(x)+'</button>').join('')+'</div><div data-feedback style="margin-top:16px"></div><p><button class="cf-btn primary" data-next style="display:none">'+(n===total?'Finalizar':'Próxima questão →')+'</button></p>';quiz.host.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>answerQuiz(+b.dataset.opt))}
function answerQuiz(sel){if(!quiz||quiz.answered)return;quiz.answered=true;const q=quiz.list[quiz.i],ok=sel===q.a;if(ok)quiz.score++;quiz.host.querySelectorAll('[data-opt]').forEach((b,i)=>{b.disabled=true;if(i===q.a)b.classList.add('good')});quiz.host.querySelector('[data-feedback]').innerHTML='<aside class="bc-native-callout '+(ok?'case':'trap')+'"><b>'+(ok?'✓ Correto':'✗ Incorreto')+'</b><div>'+E(q.e)+'</div></aside>';const nx=quiz.host.querySelector('[data-next]');nx.style.display='inline-flex';nx.onclick=()=>{if(quiz.i+1<quiz.list.length){quiz.i++;renderQuiz()}else finishQuiz()}}
function finishQuiz(){if(!quiz)return;const mode=quiz.mode,score=quiz.score,total=quiz.list.length;saveQS(mode,score);quiz.host.innerHTML='<div class="bc-native-kicker">FIXAÇÃO CONCLUÍDA</div><h1>'+score+' / '+total+'</h1><p>Resultado salvo. Esta tarefa agora conta no progresso do M20.</p><p><button class="cf-btn primary" data-done>Voltar ao M20</button></p>';quiz.host.querySelector('[data-done]').onclick=closeQuiz}
function H(w){const m=M(),a=rd('summary'),b=rd('complete'),x=X(),p=P(),acc=x.done?Math.round(x.correct/x.done*1000)/10:0,qs=QS();return '<section class="cf-module" data-cf="cpc20"><button class="cf-module-head" onclick="toggleCpcModule(\'cpc20\')"><span class="cf-module-no">MÓDULO 20</span><span class="cf-module-title">'+E(w?.title||'Processos nos tribunais, ação rescisória, IAC, IRDR e reclamação')+'</span><span class="cf-module-stat">Cobertura '+p+'%</span><span class="chev">⌄</span></button><div class="cf-module-body"><div class="cf-module-bar"><span style="width:'+p+'%"></span></div><section class="bc-native-materials bc-native-materials-static"><div class="bc-native-material-grid"><button class="bc-native-material-card" onclick="CpcM20NativeReader.open(\'summary\')"><span class="bc-native-material-icon">⚡</span><span><strong>Conteúdo resumido</strong><small>'+a.total+' capítulos</small></span><span class="bc-native-material-action"><span>'+a.done+'/'+a.total+'</span><span>→</span></span></button><button class="bc-native-material-card" onclick="CpcM20NativeReader.open(\'complete\')"><span class="bc-native-material-icon">📚</span><span><strong>Conteúdo completo</strong><small>'+b.total+' blocos</small></span><span class="bc-native-material-action"><span>'+b.done+'/'+b.total+'</span><span>→</span></span></button><button class="bc-native-material-card" onclick="cpcM20OpenMap()"><span class="bc-native-material-icon">🧠</span><span><strong>Mapa mental</strong><small>Fechamento rápido</small></span><span class="bc-native-material-action"><span>'+(m.map?'✓':'Abrir')+'</span><span>→</span></span></button></div></section><section class="cpc-study-intro" style="margin-top:12px"><div><h3>Fixação interna</h3><p>Questões autorais calibradas ao conteúdo auditado do M20.</p></div><div class="cpc-study-actions"><button class="cf-btn '+(qs.summary.done?'good':'')+'" onclick="cpcM20OpenQuiz(\'summary\')">'+(qs.summary.done?'✓ ':'')+'5 do resumido'+(qs.summary.done?' • '+qs.summary.score+'/5':'')+'</button><button class="cf-btn '+(qs.complete.done?'good':'')+'" onclick="cpcM20OpenQuiz(\'complete\')">'+(qs.complete.done?'✓ ':'')+'10 do completo'+(qs.complete.done?' • '+qs.complete.score+'/10':'')+'</button></div></section><div class="cpc-bottom-grid"><section class="cpc-mini-panel"><h4>⚖️ Lei em Dia</h4><button class="cf-btn primary" onclick="openLeiSecaEnxuta(null,\'cpc\',\'cpc-m20\')">Abrir</button> <button class="cf-btn '+(m.decorando?'good':'')+'" onclick="cpcM20Set({decorando:'+(!m.decorando)+'})">'+(m.decorando?'✓ Concluído':'Marcar concluído')+'</button></section><section class="cpc-mini-panel"><h4>🎯 Questões externas</h4><div class="cpc-external-form"><label>Feitas<input id="cpc-ext-done-w20" type="number" value="'+x.done+'"></label><label>Acertos<input id="cpc-ext-correct-w20" type="number" value="'+x.correct+'"></label><button class="cf-btn" onclick="cpcM20SaveExternal()">Salvar</button></div><div class="cpc-ext-score">'+(x.done?acc+'%':'—')+'</div></section></div></div></section>'}
function R(){try{renderAll()}catch(_){}}
function install(){if(!g.CpcStudyV1||!g.__CPC_WEEKS){setTimeout(install,100);return}if(g.CpcStudyM20)return;const prev=g.CpcStudyV1.renderMaster,pp=g.CpcStudyV1.progress;g.CpcStudyV1.progress=id=>(id===ID||id===SID)?P():pp(id);g.CpcStudyV1.renderMaster=function(){const b=prev(),w=g.__CPC_WEEKS.find(x=>x.id===ID),i=b.lastIndexOf('</div>');return w?b.slice(0,i)+H(w)+b.slice(i):b};g.CpcStudyM20=true;R()}
g.cpcM20OpenMap=map;g.cpcM20CloseMap=closeMap;g.cpcM20Set=setM;g.cpcM20SaveExternal=saveX;g.cpcM20OpenQuiz=openQuiz;g.cpcM20CloseQuiz=closeQuiz;g.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.type==='cpc-map-complete'&&e.data?.module==='w20')setM({map:true})});setTimeout(install,0);
